// =====================================
// Q.SOC - Risky Users Distribution
// =====================================

AADUserRiskEvents
| summarize RiskLevel = any(RiskLevel) by UserPrincipalName
| where tolower(RiskLevel) in ("high","medium","hidden")
| summarize Users = dcount(UserPrincipalName) by RiskLevel
| order by Users desc

// =========================================
// FortiGate Live Traffic Monitor v2.0
// =========================================

CommonSecurityLog
| where DeviceVendor =~ "Fortinet"
| where DeviceProduct =~ "Fortigate"

| extend RawExt = tostring(AdditionalExtensions)

//
// Action
//
| extend ActionRaw = tolower(extract(@"FTNTFGTaction=([^;]+)", 1, RawExt))

| extend Action = case(
    ActionRaw in ("accept","pass"), "🟢 ALLOW",
    ActionRaw == "deny", "🔴 DENY",
    ActionRaw == "drop", "🚫 DROP",
    ActionRaw == "reject", "⛔ REJECT",
    ActionRaw == "close", "🔵 CLOSE",
    ActionRaw == "server-rst", "🟡 SERVER RESET",
    ActionRaw == "client-rst", "🟠 CLIENT RESET",
    "⚪ OTHER"
)

//
// Severity
//
| extend Severity = case(
    ActionRaw in ("deny","drop","reject"), "🔴 High",
    ActionRaw == "close", "🟡 Medium",
    "🟢 Normal"
)

//
// Countries
//
| extend
    SourceCountry = extract(@"FTNTFGTsrccountry=([^;]+)", 1, RawExt),
    DestinationCountry = extract(@"FTNTFGTdstcountry=([^;]+)", 1, RawExt)

| extend
    SourceCountry = iff(SourceCountry == "Bangladesh", "🔵 Bangladesh", SourceCountry),
    DestinationCountry = iff(DestinationCountry == "Bangladesh", "🔵 Bangladesh", DestinationCountry)

//
// Policy
//
| extend PolicyName = coalesce(
    extract(@"FTNTFGTpolicyname=([^;]+)", 1, RawExt),
    "N/A"
)

//
// Service
//
| extend Service = coalesce(
    extract(@"FTNTFGTservice=([^;]+)", 1, RawExt),
    extract(@"service=([^;]+)", 1, RawExt),
    tostring(DestinationServiceName),
    tostring(ApplicationProtocol),
    "Unknown"
)

//
// Application
//
| extend Application = coalesce(
    extract(@"FTNTFGTapp=([^;]+)", 1, RawExt),
    tostring(ApplicationProtocol),
    "Unknown"
)

//
// Session
//
| extend
    DurationSec = todouble(extract(@"FTNTFGTduration=([^;]+)", 1, RawExt)),
    SessionID = extract(@"FTNTFGTsessionid=([^;]+)", 1, RawExt)

//
// Traffic
//
| extend
    UploadMB = round(todouble(coalesce(SentBytes, 0)) / 1024.0 / 1024.0, 2),
    DownloadMB = round(todouble(coalesce(ReceivedBytes, 0)) / 1024.0 / 1024.0, 2),
    TotalMB = round(
        (
            todouble(coalesce(SentBytes, 0)) +
            todouble(coalesce(ReceivedBytes, 0))
        ) / 1024.0 / 1024.0,
        2
    )

//
// Traffic Level
//
| extend TrafficLevel = case(
    TotalMB >= 1000, "🔥 Critical",
    TotalMB >= 500, "🔴 Very High",
    TotalMB >= 100, "🟠 High",
    TotalMB >= 20, "🟡 Medium",
    "🟢 Low"
)

//
// Flow
//
| extend Flow = strcat(
    SourceIP,
    ":",
    SourcePort,
    "  ➜  ",
    DestinationIP,
    ":",
    DestinationPort
)

//
// Alert Message
//
| extend AlertMessage = iff(
    isempty(trim(" ", tostring(Message))),
    "",
    strcat("🔴 ", tostring(Message))
)

//
// Display
//
| project
    TimeGenerated,
    Severity,
    Action,
    Flow,
    SourceCountry,
    DestinationCountry,
    PolicyName,
    Service,
    Application,
    AppProtocol = ApplicationProtocol,
    UploadMB,
    DownloadMB,
    TotalMB,
    TrafficLevel,
    DurationSec,
    SessionID,
    AlertMessage

| order by TimeGenerated desc
